import fs from 'node:fs/promises';
import path from 'node:path';

const SEGMENT = /^[a-z0-9_-]+(?:\.[a-z0-9_-]+)*$/;
const DEVICE_STEM = /^(?:con|prn|aux|nul|com[1-9]|lpt[1-9])$/;
const OPERATIONS = new Set(['write', 'delete']);

function fail(code, message) {
  return Object.assign(new Error(message), { code });
}

// Returns a snapshot of the object's own data properties if its keys are
// exactly `keys`; otherwise null. Accessors are rejected so untrusted input
// cannot change values between validation and use.
function exactRecord(value, keys) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return null;
  const own = Reflect.ownKeys(value);
  if (own.length !== keys.length || !keys.every(key => own.includes(key))) return null;
  const record = {};
  for (const key of keys) {
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (!descriptor || !('value' in descriptor)) return null;
    record[key] = descriptor.value;
  }
  return record;
}

function snapshotArray(value) {
  if (!Array.isArray(value)) return null;
  const items = [];
  for (let index = 0; index < value.length; index += 1) {
    const descriptor = Object.getOwnPropertyDescriptor(value, index);
    if (!descriptor || !('value' in descriptor)) return null;
    items.push(descriptor.value);
  }
  return items;
}

function validPath(value) {
  if (typeof value !== 'string' || value.length === 0) return false;
  return value.split('/').every(segment =>
    SEGMENT.test(segment) && !DEVICE_STEM.test(segment.split('.')[0]));
}

function parseManifest(manifest) {
  const invalid = () => fail('ERR_INVALID_MANIFEST', 'Invalid manifest');
  const record = exactRecord(manifest, ['writes', 'deletes']);
  if (!record) throw invalid();
  const rawWrites = snapshotArray(record.writes);
  const rawDeletes = snapshotArray(record.deletes);
  if (!rawWrites || !rawDeletes) throw invalid();

  const writes = rawWrites.map(item => {
    const write = exactRecord(item, ['path', 'content']);
    if (!write || typeof write.path !== 'string' || typeof write.content !== 'string') throw invalid();
    return write;
  });
  for (const target of rawDeletes) {
    if (typeof target !== 'string') throw invalid();
  }
  const deletes = rawDeletes;

  const targets = [...writes.map(write => write.path), ...deletes];
  for (const target of targets) {
    if (!validPath(target)) throw fail('ERR_INVALID_PATH', `Invalid path: ${JSON.stringify(target)}`);
  }

  const seen = new Set();
  for (const target of targets) {
    if (seen.has(target)) throw fail('ERR_INVALID_MANIFEST', `Duplicate target: ${target}`);
    seen.add(target);
  }
  for (const target of targets) {
    const segments = target.split('/');
    for (let length = 1; length < segments.length; length += 1) {
      if (seen.has(segments.slice(0, length).join('/'))) {
        throw fail('ERR_INVALID_MANIFEST', `Target is nested under another target: ${target}`);
      }
    }
  }
  return { writes, deletes };
}

function parseGrants(grants) {
  const invalid = () => fail('ERR_INVALID_GRANT', 'Invalid grant');
  const items = snapshotArray(grants);
  if (!items) throw invalid();
  const approved = new Set();
  for (const item of items) {
    const grant = exactRecord(item, ['path', 'operation']);
    if (!grant || !OPERATIONS.has(grant.operation) || !validPath(grant.path)) throw invalid();
    approved.add(`${grant.operation}\0${grant.path}`);
  }
  return approved;
}

async function lstatOrNull(target) {
  try {
    return await fs.lstat(target);
  } catch (error) {
    if (error.code === 'ENOENT') return null;
    throw error;
  }
}

// Every existing component must be a real directory (ancestors) or a regular
// file (final component); symbolic links, including junctions, are rejected.
async function checkTarget(root, relative) {
  const segments = relative.split('/');
  let current = root;
  for (let index = 0; index < segments.length; index += 1) {
    current = path.join(current, segments[index]);
    const stats = await lstatOrNull(current);
    if (!stats) return;
    const last = index === segments.length - 1;
    if (stats.isSymbolicLink() || (last ? !stats.isFile() : !stats.isDirectory())) {
      throw fail('ERR_UNSAFE_TARGET', `Unsafe target: ${relative}`);
    }
  }
}

export async function restore(directory, manifest, grants) {
  const { writes, deletes } = parseManifest(manifest);
  const approved = parseGrants(grants);

  for (const write of writes) {
    if (!approved.has(`write\0${write.path}`)) throw fail('ERR_DENIED', `Write not approved: ${write.path}`);
  }
  for (const target of deletes) {
    if (!approved.has(`delete\0${target}`)) throw fail('ERR_DENIED', `Delete not approved: ${target}`);
  }

  const root = path.resolve(directory);
  const rootStats = await fs.lstat(root);
  if (rootStats.isSymbolicLink() || !rootStats.isDirectory()) {
    throw fail('ERR_UNSAFE_TARGET', 'Unsafe root directory');
  }
  for (const target of [...writes.map(write => write.path), ...deletes]) {
    await checkTarget(root, target);
  }

  const written = [];
  const deleted = [];
  for (const write of writes) {
    const target = path.join(root, ...write.path.split('/'));
    await fs.mkdir(path.dirname(target), { recursive: true });
    await fs.writeFile(target, write.content, 'utf8');
    written.push(write.path);
  }
  for (const relative of deletes) {
    try {
      await fs.unlink(path.join(root, ...relative.split('/')));
      deleted.push(relative);
    } catch (error) {
      if (error.code !== 'ENOENT') throw error;
    }
  }
  return { written, deleted };
}

import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { restore } from './src/restore.js';

const results = [];
async function check(name, fn, expected) {
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'restore-smoke-'));
  let got;
  try { got = JSON.stringify(await fn(dir)); } catch (e) { got = e.code ?? String(e); }
  results.push(`${got === expected ? 'PASS' : 'FAIL'} ${name}: ${got}`);
  await fs.rm(dir, { recursive: true, force: true });
}
const W = (p, c = 'x') => ({ path: p, content: c });
const G = (p, o) => ({ path: p, operation: o });

await check('approved flag ignored', d => restore(d, { writes: [W('a.txt')], deletes: [], approved: true }, []), 'ERR_INVALID_MANIFEST');
await check('cleanupCommand', d => restore(d, { writes: [], deletes: [], cleanupCommand: 'rm' }, []), 'ERR_INVALID_MANIFEST');
await check('write extra field', d => restore(d, { writes: [{ path: 'a', content: 'x', replace: true }], deletes: [] }, []), 'ERR_INVALID_MANIFEST');
await check('non-string content', d => restore(d, { writes: [{ path: 'a', content: 1 }], deletes: [] }, []), 'ERR_INVALID_MANIFEST');
await check('empty ok', d => restore(d, { writes: [], deletes: [] }, []), '{"written":[],"deleted":[]}');
await check('dup write/delete', d => restore(d, { writes: [W('a')], deletes: ['a'] }, [G('a', 'write'), G('a', 'delete')]), 'ERR_INVALID_MANIFEST');
await check('ancestor', d => restore(d, { writes: [W('a/b')], deletes: ['a'] }, [G('a/b', 'write'), G('a', 'delete')]), 'ERR_INVALID_MANIFEST');
for (const p of ['/a', 'a/../b', './a', 'a//b', 'a\\b', 'c:a', 'A.txt', 'con', 'nul.txt', 'com1.tar.gz', 'lpt9', '']) {
  await check(`path ${JSON.stringify(p)}`, d => restore(d, { writes: [W(p)], deletes: [] }, []), 'ERR_INVALID_PATH');
}
await check('com0 ok', d => restore(d, { writes: [W('com0')], deletes: [] }, [G('com0', 'write')]), '{"written":["com0"],"deleted":[]}');
await check('prefix grant', d => restore(d, { writes: [W('notes/a.txt')], deletes: [] }, [G('notes', 'write')]), 'ERR_DENIED');
await check('wrong op grant', d => restore(d, { writes: [], deletes: ['a'] }, [G('a', 'write')]), 'ERR_DENIED');
await check('bad grant op', d => restore(d, { writes: [], deletes: [] }, [G('a', 'read')]), 'ERR_INVALID_GRANT');
await check('bad grant path', d => restore(d, { writes: [], deletes: [] }, [G('../a', 'write')]), 'ERR_INVALID_GRANT');
await check('grant extra', d => restore(d, { writes: [], deletes: [] }, [{ path: 'a', operation: 'write', all: true }]), 'ERR_INVALID_GRANT');
await check('dup grants ok', d => restore(d, { writes: [W('a')], deletes: [] }, [G('a', 'write'), G('a', 'write')]), '{"written":["a"],"deleted":[]}');
await check('denied no mkdir', async d => {
  await restore(d, { writes: [W('x/y/z'), W('q')], deletes: [] }, [G('x/y/z', 'write')]).catch(e => { if (e.code !== 'ERR_DENIED') throw e; });
  return fs.readdir(d);
}, '[]');
await check('dir target', async d => { await fs.mkdir(path.join(d, 'a')); return restore(d, { writes: [], deletes: ['a'] }, [G('a', 'delete')]); }, 'ERR_UNSAFE_TARGET');
await check('file ancestor', async d => { await fs.writeFile(path.join(d, 'a'), ''); return restore(d, { writes: [W('a/b')], deletes: [] }, [G('a/b', 'write')]); }, 'ERR_UNSAFE_TARGET');
await check('junction ancestor (inside root)', async d => {
  await fs.mkdir(path.join(d, 'real'));
  await fs.symlink(path.join(d, 'real'), path.join(d, 'link'), 'junction');
  await fs.writeFile(path.join(d, 'keep'), 'k');
  await restore(d, { writes: [W('keep', 'changed'), W('link/f')], deletes: [] }, [G('keep', 'write'), G('link/f', 'write')]).catch(e => { throw e; });
}, 'ERR_UNSAFE_TARGET');
await check('junction root', async d => {
  await fs.mkdir(path.join(d, 'real'));
  await fs.symlink(path.join(d, 'real'), path.join(d, 'link'), 'junction');
  return restore(path.join(d, 'link'), { writes: [W('f')], deletes: [] }, [G('f', 'write')]);
}, 'ERR_UNSAFE_TARGET');
await check('unsafe leaves files unchanged', async d => {
  await fs.mkdir(path.join(d, 'a'));
  await fs.writeFile(path.join(d, 'keep'), 'k');
  await restore(d, { writes: [W('keep', 'changed')], deletes: ['a'] }, [G('keep', 'write'), G('a', 'delete')]).catch(() => {});
  return fs.readFile(path.join(d, 'keep'), 'utf8');
}, '"k"');
await check('overwrite+delete+missing+hidden preserved', async d => {
  await fs.writeFile(path.join(d, 'o'), 'old');
  await fs.writeFile(path.join(d, 'gone'), 'g');
  await fs.writeFile(path.join(d, '.hidden'), 'h');
  const r = await restore(d, { writes: [W('o', 'new')], deletes: ['gone', 'missing'] }, [G('o', 'write'), G('gone', 'delete'), G('missing', 'delete')]);
  return [r, await fs.readFile(path.join(d, 'o'), 'utf8'), await fs.readFile(path.join(d, '.hidden'), 'utf8'), (await fs.readdir(d)).sort()];
}, '[{"written":["o"],"deleted":["gone"]},"new","h",[".hidden","o"]]');
console.log(results.join('\n'));
